#include "resources.h"

#include <cstring>

namespace dxg {

static const Resource *find(const std::string &name)
{
  for (int i = 0; i < g_numResources; i++)
  {
    if (name == g_resources[i].name) return &g_resources[i];
  }
  return nullptr;
}

std::string resource(const std::string &name)
{
  const Resource *r = find(name);
  if (r == nullptr) return std::string();
  return std::string(reinterpret_cast<const char *>(r->data), static_cast<size_t>(r->size));
}

bool hasResource(const std::string &name)
{
  return find(name) != nullptr;
}

} // namespace dxg

