#ifndef DXG_CONFIGOPTIONS_H
#define DXG_CONFIGOPTIONS_H

namespace dxg {

/** How the value of a configuration tag is interpreted. */
enum class OptType
{
  Bool,
  Int,
  Enum,
  String,
  List
};

/** Static description of one configuration tag. */
struct OptDef
{
  const char *name;
  OptType type;
  const char *dflt;                 //!< default for Bool/Int/Enum/String
  const char *const *dfltList;      //!< nullptr terminated default for List
  const char *const *values;        //!< nullptr terminated allowed set for Enum
  int minVal;
  int maxVal;
  const char *unused;
};

extern const OptDef g_optDefs[];
extern const int g_numOptDefs;

/** Comment block printed in front of tag \c i by -g and -u. */
extern const char *const g_optDocs[];

/** One line of the template file: either a section banner or a tag. */
struct LayoutEntry
{
  bool isSection;
  const char *section;
  int optIdx;
};

extern const LayoutEntry g_layout[];
extern const int g_numLayout;

/** Comment block at the very top of a generated template. */
extern const char *const g_preamble[];

/** A tag that older versions understood; \a replacement may be empty. */
struct ObsoleteOpt
{
  const char *name;
  const char *replacement;
};

extern const ObsoleteOpt g_obsoleteOpts[];
extern const int g_numObsoleteOpts;

} // namespace dxg

#endif

